import { useId } from "react";

/**
 * The Latchpoint mark.
 *
 * With `animated`, it plays the same sequence as the animated email-signature
 * GIF: the ember square winds up and flies off spinning, the outline un-draws
 * and draws itself back on with an ember spark riding the tip, the square
 * swoops back in and lands with a squash, then a glow, shockwave rings, an
 * outline jiggle and a light glint, before resting and repeating.
 *
 * The motion is plain CSS keyframes generated by
 * scripts/generate-logo-animation.py (src/app/logo-anim.css), so it costs no
 * JavaScript and switches itself off under prefers-reduced-motion, where the
 * mark just sits at rest. At rest the animated mark is the same shape as the
 * static one.
 */
export function Logomark({ className = "", animated = false }: { className?: string; animated?: boolean }) {
  // Unique per instance: the header and footer logos can be on one page.
  const uid = useId().replace(/:/g, "");

  if (!animated) {
    return (
      <svg viewBox="2.5 1.2 20.3 20.3" fill="none" className={className} aria-hidden="true">
        <rect x="3.5" y="3.5" width="17" height="17" rx="6" stroke="currentColor" strokeWidth="2" />
        <rect x="14.8" y="1.2" width="8" height="8" rx="2.7" fill="var(--accent)" />
      </svg>
    );
  }

  // The outline as one drawable path (same rounded square as the static rect),
  // starting just left of the chip and running clockwise.
  const ring = "M14.5 3.5 A6 6 0 0 1 20.5 9.5 V14.5 A6 6 0 0 1 14.5 20.5 H9.5 A6 6 0 0 1 3.5 14.5 V9.5 A6 6 0 0 1 9.5 3.5 H14.5";

  return (
    <svg
      viewBox="2.5 1.2 20.3 20.3"
      fill="none"
      className={`${className} lp-logo-anim overflow-visible`}
      aria-hidden="true"
    >
      <defs>
        <radialGradient id={`${uid}-glow`}>
          <stop offset="0" stopColor="var(--accent)" stopOpacity="0.85" />
          <stop offset="0.6" stopColor="var(--accent)" stopOpacity="0.3" />
          <stop offset="1" stopColor="var(--accent)" stopOpacity="0" />
        </radialGradient>
        <linearGradient id={`${uid}-glint`} x1="0" x2="1" y1="0" y2="0">
          <stop offset="0" stopColor="#fff" stopOpacity="0" />
          <stop offset="0.5" stopColor="#fff" stopOpacity="0.8" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        {/* The glint only shows on the mark itself, never on the page behind it. */}
        <mask id={`${uid}-mask`} maskUnits="userSpaceOnUse" x="-6" y="-6" width="36" height="36">
          <path d={ring} stroke="#fff" strokeWidth="2" strokeLinecap="round" />
          <rect x="14.8" y="1.2" width="8" height="8" rx="2.7" fill="#fff" />
        </mask>
      </defs>

      <circle className="lp-glow" cx="18.8" cy="5.2" r="10" fill={`url(#${uid}-glow)`} />
      <rect className="lp-shock lp-shock-1" x="14.7" y="1.1" width="8.2" height="8.2" rx="1.4" stroke="var(--accent)" strokeWidth="1" vectorEffect="non-scaling-stroke" />
      <rect className="lp-shock lp-shock-2" x="14.7" y="1.1" width="8.2" height="8.2" rx="1.4" stroke="var(--accent)" strokeWidth="1" vectorEffect="non-scaling-stroke" />

      <path className="lp-ring" d={ring} pathLength={1} strokeDasharray={1} stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <rect className="lp-chip" x="14.8" y="1.2" width="8" height="8" rx="2.7" fill="var(--accent)" />
      <circle className="lp-spark" cx="0" cy="0" r="1.5" fill="var(--accent)" />

      <g mask={`url(#${uid}-mask)`}>
        <g transform="rotate(45 12 12)">
          <rect className="lp-glint" x="8.5" y="-12" width="7" height="48" fill={`url(#${uid}-glint)`} />
        </g>
      </g>
    </svg>
  );
}

export function Wordmark({ className = "", animated = false }: { className?: string; animated?: boolean }) {
  return (
    <span className={`inline-flex items-center gap-2.5 ${className}`}>
      <Logomark className="size-6 text-text" animated={animated} />
      <span className="font-medium tracking-tight text-text">
        Latchpoint<span className="text-text-muted"> Studios</span>
      </span>
    </span>
  );
}
